'use strict';
/**
 * agent-groups.js – create agents per Keycloak group in LibreChat (runs INSIDE the librechat container)
 *
 * Only called via scripts/agent-groups.sh:
 *   (plan line + this file) | docker exec -i -w /app librechat node -   (KIRA_PLAN = base64 JSON)
 *
 * Plan (from config/agent-groups.json, generated by librechat-config.py):
 *   { enabled, roles: { <group>: [model specs] }, endpoint: "Bifrost", endpoints: [all custom endpoints],
 *     builders: { <model group>: {...} }, builder_group, image_agent: { id, endpoint, model } | null, remove: [<group>] }
 *
 * Per group: a LibreChat role of the same name (permissions like USER) + a role config with its own
 * agent list (modelSpecs.list). With own agents the roles may also create agents (AGENTS.CREATE) –
 * the builder itself only appears for builders (per-user profile, builder-sync.py).
 * USER (users without a matching group) sees NO agent: all endpoints are hidden for USER (tombstones),
 * which also removes all agents (model specs).
 * Image agent (stored agent): provider = its own endpoint (image_agent.endpoint), so that the builders'
 * provider limits do not block it.
 * ADMIN gets no role config and sees the full list from librechat.yaml; only its permissions are set
 * (plan.system_permissions: create/share agents, "+").
 * Removed groups: config and role are deleted, their members fall back to USER.
 * Uses LibreChat's own methods (~/models), no direct database writes.
 */

const DESCRIPTION = 'KIRA: agents per Keycloak group (managed by /opt/kira/scripts/agent-groups.sh)';
const ROLE = 'role';
const ROLE_MODEL = 'Role';
const USER = 'USER';
const AGENTS = 'AGENTS';

async function sync(m, plan, log, db) {
  const base = await m.getRoleByName(USER);
  if (!base || !base.permissions) {
    throw new Error('role USER not found – has LibreChat fully started?');
  }
  const roles = plan.enabled ? plan.roles || {} : {};
  const builders = plan.enabled ? Object.keys(plan.builders || {}) : [];
  const permissions = JSON.parse(JSON.stringify(base.permissions));
  // the interface settings of librechat.yaml (plan.role_permissions) win over the USER copy
  for (const [type, values] of Object.entries(plan.role_permissions || {})) {
    permissions[type] = { ...(permissions[type] || {}), ...values };
  }
  if (builders.length) {
    // creating agents (the builder only appears for builders); sharing stays as for USER
    permissions[AGENTS] = { ...(permissions[AGENTS] || {}), CREATE: true };
  }
  for (const [name, list] of Object.entries(roles)) {
    if (name.toUpperCase() === USER || name.toUpperCase() === 'ADMIN') {
      throw new Error(`group ${name}: reserved name`);
    }
    const existing = await m.getRoleByName(name);
    if (existing) {
      await m.updateRoleByName(name, { permissions, description: DESCRIPTION });
      log(`role ${name}: permissions updated (same as USER${builders.length ? ' + create agents' : ''})`);
    } else {
      await m.createRoleByName({ name, description: DESCRIPTION, permissions });
      log(`role ${name}: created (permissions same as USER${builders.length ? ' + create agents' : ''})`);
    }
    await m.upsertConfig(ROLE, name, ROLE_MODEL, { modelSpecs: { list } });
    log(`role ${name}: ${list.length} agents (${list.map((s) => s.name).join(', ')})`);
  }
  if (plan.enabled) {
    if (!plan.endpoint) {
      throw new Error('plan without endpoint');
    }
    const hidden = plan.endpoints && plan.endpoints.length ? plan.endpoints : [plan.endpoint];
    await m.upsertConfig(ROLE, USER, ROLE_MODEL, {});
    await m.tombstoneConfigField(
      ROLE,
      USER,
      ROLE_MODEL,
      // + the agent list itself: the image agent (stored agent) does not hang on a custom endpoint
      hidden.map((name) => `endpoints.custom[${JSON.stringify(name)}]`).concat(['modelSpecs.list']),
    );
    log('role USER (no group): no agent (endpoints hidden)');
  } else if (await m.findConfigByPrincipal(ROLE, USER, { includeInactive: true })) {
    await m.deleteConfig(ROLE, USER);
    log('role USER: own config removed (all agents from librechat.yaml again)');
  }
  for (const name of plan.remove || []) {
    if (Object.prototype.hasOwnProperty.call(roles, name)) {
      continue;
    }
    if (await m.findConfigByPrincipal(ROLE, name, { includeInactive: true })) {
      await m.deleteConfig(ROLE, name);
    }
    const existing = await m.getRoleByName(name);
    if (existing && existing.description === DESCRIPTION) {
      await m.deleteRoleByName(name);
      log(`role ${name}: removed (members are USER again)`);
    } else if (existing) {
      log(`role ${name}: not created by KIRA – kept, only its agent list was removed`);
    }
  }
  // system roles: only what KIRA sets beyond librechat.yaml (e.g. "+"/multiConvo only for ADMIN)
  for (const [roleName, wanted] of Object.entries(plan.system_permissions || {})) {
    const role = roleName === USER ? base : await m.getRoleByName(roleName);
    if (!role || !role.permissions) {
      continue;
    }
    const current = JSON.parse(JSON.stringify(role.permissions));
    let changed = false;
    for (const [type, values] of Object.entries(wanted)) {
      for (const [perm, value] of Object.entries(values)) {
        if (!current[type] || current[type][perm] !== value) {
          current[type] = { ...(current[type] || {}), [perm]: value };
          changed = true;
        }
      }
    }
    if (changed) {
      await m.updateRoleByName(roleName, { permissions: current });
      log(`role ${roleName}: ${Object.keys(wanted).join(', ')} adjusted`);
    }
  }
  await moveImageAgent(m, plan.image_agent, log);
  if (!builders.length && db && typeof plan.builder_priority === 'number') {
    // no own agents (any more): remove the builder profiles (builder-sync.py only cleans up while it runs)
    const managed = await db.findManaged(plan.builder_priority);
    for (const cfg of managed) {
      await m.deleteConfig('user', String(cfg.principalId));
    }
    if (managed.length) {
      log(`builder profiles: ${managed.length} removed (no own agents defined)`);
    }
  }
}

const IMAGE_TOOL = 'image_gen_oai';

/** Image agent on its own endpoint (and a model of that endpoint) – stored agents keep the provider they were saved with. */
async function moveImageAgent(m, image, log) {
  if (!image || !image.id) {
    return;
  }
  const agent = await m.getAgent({ id: image.id });
  if (!agent) {
    log(`image agent ${image.id}: not found – check AGENT_ID in agents/40-images.env`);
    return;
  }
  // keep the image tool on the agent (e.g. if it was removed by mistake in the agent builder)
  const tools = Array.isArray(agent.tools) ? agent.tools : [];
  const update = {};
  if (agent.provider !== image.endpoint || agent.model !== image.model) {
    update.provider = image.endpoint;
    update.model = image.model;
  }
  if (!tools.includes(IMAGE_TOOL)) {
    update.tools = [...tools, IMAGE_TOOL];
  }
  if (!Object.keys(update).length) {
    return;
  }
  await m.updateAgent({ id: image.id }, update, { skipVersioning: true });
  if (update.provider) {
    log(`image agent ${image.id}: provider "${image.endpoint}", model ${image.model} (was ${agent.provider}, ${agent.model})`);
  }
  if (update.tools) {
    log(`image agent ${image.id}: image tool added again`);
  }
}

async function main() {
  require('module-alias')({ base: '/app/api' });
  // like the LibreChat server: '~/db' registers the mongoose models (createModels) – without it the methods
  // from '~/models' find no Role/Config model ("Cannot read properties of undefined (reading 'findOne')")
  const { connectDb } = require('~/db');
  const m = require('~/models');
  const raw = process.env.KIRA_PLAN;
  if (!raw) {
    throw new Error('KIRA_PLAN is missing');
  }
  const plan = JSON.parse(Buffer.from(raw, 'base64').toString('utf8'));
  await connectDb();
  const mongoose = require('mongoose');
  const db = {
    findManaged: (priority) =>
      mongoose.models.Config.find({ principalType: 'user', priority }).select('principalId').lean(),
  };
  await sync(m, plan, (line) => console.log(`  ${line}`), db);
}

// run via stdin (node -): require.main is undefined there, so only the test switch decides
if (!process.env.KIRA_TEST) {
  main()
    .then(() => process.exit(0))
    .catch((err) => {
      console.error(`Error: ${err && err.message ? err.message : err}`);
      process.exit(1);
    });
}

module.exports = { sync, moveImageAgent, DESCRIPTION };
